+{
+  FAR struct velapoka_fb_s *fb = (FAR struct velapoka_fb_s *)vtable;
+  size_t offset;
+  size_t length;
+
+  if (area == NULL || area->w == 0 || area->h == 0 ||
+      area->x >= fb->vinfo.xres || area->y >= fb->vinfo.yres ||
+      area->x + area->w > fb->vinfo.xres ||
+      area->y + area->h > fb->pinfo.yres_virtual)
+    {
